:root {
  --night: #302542;
  --paper: #fff9ed;
  --orange: #f47b32;
  --mint: #b8dfc6;
  --plum: #6b466f;
}

.porch-card {
  box-sizing: border-box;
  width: 460px;
  padding: 16px;
  background: var(--paper);
  border: 2px solid var(--night);
  border-radius: 18px;
  color: var(--night);
}

.porch-card header {
  display: flex;
  align-items: center;
  gap: 12px;
}

.glow {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: var(--orange);
  color: var(--paper);
  display: grid;
  place-items: center;
  font-size: 20px;
}

.heading {
  flex: 1;
}

.heading p {
  margin: 0 0 2px;
  color: var(--plum);
  font-size: 11px;
  font-weight: 700;
}

h1 {
  margin: 0;
  font-size: 20px;
  line-height: 1.1;
}

.open {
  padding: 5px 8px;
  border-radius: 999px;
  background: var(--mint);
  color: var(--night);
  font-size: 10px;
  font-weight: 700;
}

.message {
  margin: 14px 0 0;
  padding-top: 12px;
  border-top: 1px solid var(--plum);
  font-size: 14px;
  line-height: 1.35;
}
